<#
  AI Task Manager - step-by-step task creation + Gemini overload handling.

  Run from EITHER your project folder ("AI Manager", containing backend\ and
  frontend\) OR from the backend folder. It finds the right place itself.

  What it changes
    Backend
      - New step order. Recurring: dates -> repeat -> how many reminder
        windows -> start/end time of each window. Repeat Until Done:
        repeat -> how many windows -> each window.
      - Gemini writes a clear title and a short description.
      - Times without AM/PM ("4:22") are no longer guessed; it asks.
      - If Gemini is overloaded: tries backup models, and if all fail,
        reads "Create buy"-style requests locally so you can continue.
    Frontend
      - Tap-to-answer chips (Every day / Weekdays / AM / PM ...).
      - Confirmation card shows type, description and every reminder window.
#>

$ErrorActionPreference = "Stop"

if ((Test-Path "backend\src") -and (Test-Path "frontend\lib")) {
  $root = (Get-Location).Path
} elseif ((Test-Path "src\modules") -and (Test-Path "..\frontend\lib")) {
  $root = (Resolve-Path "..").Path
} else {
  Write-Host "ERROR: run this from your project folder (with backend\ and frontend\ inside) or from backend\." -ForegroundColor Red
  exit 1
}

$backup = Join-Path $root ("backup_assistant_{0}" -f (Get-Date -Format "yyyyMMdd_HHmmss"))
New-Item -ItemType Directory -Path $backup -Force | Out-Null
Write-Host "Project folder: $root" -ForegroundColor Cyan
Write-Host "Backing up current files to $backup" -ForegroundColor Cyan

$files = [ordered]@{}
$files["backend\src\modules\assistant\create_flow.py"] = ""
$files["backend\src\modules\assistant\slot_filler.py"] = ""
$files["backend\src\modules\assistant\draft_validation.py"] = ""
$files["backend\src\modules\assistant\drafts\service.py"] = ""
$files["backend\src\modules\assistant\task_parser.py"] = ""
$files["backend\src\modules\assistant\prompts\task_command_prompt.py"] = ""
$files["backend\src\modules\assistant\providers\gemini_provider.py"] = ""
$files["backend\src\modules\assistant\service.py"] = ""
$files["backend\tests\test_assistant_followups.py"] = ""
$files["backend\tests\test_assistant_task_commands.py"] = ""
$files["frontend\lib\features\assistant\data\assistant_repository.dart"] = ""
$files["frontend\lib\features\assistant\presentation\assistant_screen.dart"] = ""

foreach ($rel in $files.Keys) {
  $path = Join-Path $root $rel
  if (Test-Path $path) {
    $dest = Join-Path $backup $rel
    New-Item -ItemType Directory -Path (Split-Path $dest -Parent) -Force | Out-Null
    Copy-Item $path $dest -Force
  }
  $dir = Split-Path $path -Parent
  if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
  [System.IO.File]::WriteAllBytes($path, [Convert]::FromBase64String($files[$rel]))
  Write-Host ("  updated  " + $rel) -ForegroundColor Green
}

Write-Host ""
Push-Location (Join-Path $root "backend")
python -m compileall -q src
$ok = ($LASTEXITCODE -eq 0)
Pop-Location

if ($ok) {
  Write-Host "Backend compile OK." -ForegroundColor Green
  Write-Host ""
  Write-Host "Next:" -ForegroundColor Cyan
  Write-Host "  1. Restart the backend:   cd backend ; python -m src.server"
  Write-Host "  2. Rebuild the app:       cd frontend ; flutter run"
  Write-Host "  3. Optional tests:        cd backend ; python -m pytest tests/test_assistant_followups.py -q"
} else {
  Write-Host "Backend compile reported a problem - your originals are in $backup" -ForegroundColor Yellow
}
